"""Deterministic contract tests for the foundational project documents."""

from pathlib import Path
import unittest


ROOT = Path(__file__).resolve().parents[1]


class FoundationContractTests(unittest.TestCase):
    def test_architecture_contract(self) -> None:
        text = (ROOT / "ARCHITECTURE.md").read_text(encoding="utf-8")
        required = [
            "standalone executable named `jq`",
            "Exit status `0`",
            "Exit status `3`",
            "Exit status `5`",
            "Generators are the primary runtime abstraction",
        ]
        for token in required:
            self.assertIn(token, text)

    def test_architecture_stack_and_boundaries(self) -> None:
        text = (ROOT / "ARCHITECTURE.md").read_text(encoding="utf-8")
        self.assertIn("Python 3.11 or newer, standard library only", text)
        self.assertIn("POSIX `sh`", text)
        self.assertIn("third-party or system jq implementation", text)
        for module in ("Lexer", "Parser", "Runtime", "Values", "Paths", "Builtins"):
            self.assertIn(f"| {module} |", text)

    def test_metadata_declares_cli_delivery_contract(self) -> None:
        fields: dict[str, str] = {}
        for line in (ROOT / "METADATA.md").read_text(encoding="utf-8").splitlines():
            if ":" in line and not line.startswith("#"):
                key, value = line.split(":", 1)
                fields[key] = value.strip()

        self.assertEqual(fields["display_name"], "jq Interpreter")
        self.assertEqual(fields["project_shape"], "cli")
        self.assertEqual(fields["executable"], "./jq")
        self.assertEqual(fields["stack"], "Python 3.11+ standard library; POSIX sh")
        self.assertEqual(fields["runtime_dependencies"], "none")
        self.assertEqual(fields["compile_exit_code"], "3")
        self.assertEqual(fields["runtime_exit_code"], "5")


if __name__ == "__main__":
    unittest.main()
import json
import subprocess
import unittest
from pathlib import Path

from lexer import Lexer, LexError


ROOT = Path(__file__).resolve().parents[1]


class LexerTests(unittest.TestCase):
    def test_located_tokens_cover_names_formats_and_operators(self):
        tokens = Lexer('foo .bar $x @uri //').tokens()
        self.assertEqual([t.kind for t in tokens], ["IDENT", "FIELD", "BINDING", "FORMAT", "//"])
        self.assertEqual((tokens[1].line, tokens[1].column), (1, 5))

    def test_comments_and_continuation_are_ignored(self):
        self.assertEqual([t.value for t in Lexer('1 # comment\n + 2').tokens()], [1, "+", 2])

    def test_invalid_escape_is_lexical_error(self):
        with self.assertRaises(LexError):
            Lexer(r'"u\vw"').tokens()

    def test_cli_acceptance_literals(self):
        result = subprocess.run([str(ROOT / "jq"), "-c", '"alpha"'], input="null\n", text=True, capture_output=True)
        self.assertEqual(result.returncode, 0)
        self.assertEqual(result.stdout, json.dumps("alpha", separators=(",", ":")) + "\n")

    def test_cli_acceptance_interpolation(self):
        result = subprocess.run([str(ROOT / "jq"), "-c", r'"value=\(.)"'], input="7\n", text=True, capture_output=True)
        self.assertEqual(result.returncode, 0)
        self.assertEqual(result.stdout, '"value=7"\n')


if __name__ == "__main__":
    unittest.main()
# jq Interpreter

A standalone Python interpreter for the jq language that reads JSON from stdin and emits
filtered JSON values.

## Command-line interface

Run a filter in compact-output mode:

```sh
./jq -c '<program>' < input.json
```

The program reads JSON values from standard input and writes each generated result as one
compact JSON value per line to standard output. Diagnostics are written to standard error.

Exit codes:

- `0` — compilation and execution completed successfully.
- `3` — the jq program could not be compiled.
- `5` — the compiled program raised a runtime error.

The implementation uses only the Python standard library and does not depend on a system
jq executable or a third-party package.

## Verification

Run the supplied conformance workflow from the application root:

```sh
sh sources/full_test.sh
```

